mapper.select:


    commonGroup.deleted_flag = 'N'
    and commonGroup.remark like concat('%', #{remark}, '%')
    and commonGroup.name like concat('%', #{name}, '%')
    and commonGroup.code like concat('%', #{code}, '%')
    and commonGroup.module_type = #{moduleType}
    and commonGroup.description like concat('%',
        #{description}, '%')

    and commonGroup.group_type = #{groupType}
    and commonGroup.organization_id =
        #{organizationId}

    and commonGroup.department_id = #{departmentId}

        and

            (
            commonGroup.remark like concat('%', #{item}, '%')
            )



order by commonGroup.created_time desc

select commonGroup.tenant_id, commonGroup.revision, commonGroup.created_by, commonGroup.created_time, commonGroup.updated_by, commonGroup.updated_time, commonGroup.deleted_by, commonGroup.deleted_time, commonGroup.deleted_flag, commonGroup.id, commonGroup.remark, commonGroup.name, commonGroup.code, commonGroup.module_type, commonGroup.description, commonGroup.group_type, commonGroup.organization_id, commonGroup.department_id from system_common_group as commonGroup left join system_app_common_group as appCommonGroup on appCommonGroup.common_group_id = commonGroup.id and appCommonGroup.deleted_flag = 'N'
commonGroup.deleted_flag = 'N' and appCommonGroup.app_id = #{appId}
order by commonGroup.created_time desc
